import pprint


class MsgFieldsList(list):
    """List that converts its elements to MessageField objects during creation"""
    def __init__(self, init_list):
        """
        Basic initialization.

        :param init_list:
        """
        converted_init_list = []
        for arg in init_list:
            if isinstance(arg, dict):
                arg = MessageField(arg)
            elif isinstance(arg, list):
                arg = MsgFieldsList(arg)

            converted_init_list.append(arg)
        super(MsgFieldsList, self).__init__(converted_init_list)

    def __contains__(self, key):
        """
        Search deep inside nested dicts and return True if key is found in nested structures
        Question is on domain protocol level
        eg:
            nested_key in msg_fields_list_instance
        """
        if super(MsgFieldsList, self).__contains__(key):
            return True
        paths2key = KeyFindingDict._find_paths2key(self, key, container_name="list")
        return len(paths2key) > 0

    def get_value_by_unique_key(self, key):
        """
        Search deep inside itself for value of given key.

        If key exists in container and is unique we get value.
        If multiple such keys exist in container - AmbiguousKeyError is raised
        If given key doesn't exist inside container we return None or raise NotFoundKeyError

        :param key:                    key to search value by
        :return:                       value under key
        """
        return KeyFindingDict._get_value_by_unique_key(self, key)

    def get_all_values_by_key(self, key):
        """
        Search deep inside itself for all values under given key.

        If key exists in container and is unique we get list with single value.
        If multiple such keys exist in container - we get list of all that values
        If given key doesn't exist inside container we raise NotFoundKeyError

        :param key:                    key to search value by
        :return:                       all values under key
        """
        return KeyFindingDict._get_all_values_by_key(self, key)

    def key_not_occurred(self, key):
        """
        Search deep inside itself if given key is NOT present.

        If key doesn't exists True is returned, that's why NotFoundKey exception is handled gracefully.
        If given key exist inside container we raise FoundKey

        :param key:                    key to search value by
        :raises FoundKey:              when key exists within container
        :return:                       True is not exists
        """
        captured_values = []
        try:
            captured_values = KeyFindingDict._get_all_values_by_key(self, key)
        except NotFoundKey:
            pass

        if captured_values:
            raise FoundKey(key=key, container=self)

        return True


class KeyFindingDict(dict):
    """Dict with ability to find key deep inside nested dict"""
    __slots__ = []

    def __getitem__(self, key):
        val = dict.__getitem__(self, key)
        if isinstance(val, dict):
            dict.__setitem__(self, key, MessageField(val))
            return dict.__getitem__(self, key)
        if isinstance(val, list):
            dict.__setitem__(self, key, MsgFieldsList(val))
            return dict.__getitem__(self, key)
        return val

    def __contains__(self, key):
        """
        Search deep inside nested dict and return True if key is found in nested structures
        Question is on domain protocol level
        eg:
            nested_key in key_finding_dict_instance
        """
        if super(KeyFindingDict, self).__contains__(key):
            return True
        paths2key = KeyFindingDict._find_paths2key(self, key, container_name="dict")
        return len(paths2key) > 0

    def get_value_by_unique_key(self, key):
        """
        Search deep inside itself for value of given key.

        If key exists in container and is unique we get value.
        If multiple such keys exist in container - AmbiguousKeyError is raised
        If given key doesn't exist inside container we return None or raise NotFoundKeyError

        :param key:                    key to search value by
        :return:                       value under key
        """
        return KeyFindingDict._get_value_by_unique_key(self, key)

    @staticmethod
    def _get_value_by_unique_key(container, key):
        param_name = "container"
        paths2key = KeyFindingDict._find_paths2key(container, key, param_name)
        if len(paths2key) > 1:
            raise AmbiguousKey(key=key, container=container, access_paths2key=paths2key)
        if len(paths2key) == 1:
            unique_path2key = paths2key[0]
            value = eval(unique_path2key)  # pylint: disable=eval-used
            return value
        raise NotFoundKey(key=key, container=container)

    def get_all_values_by_key(self, key):
        """
        Search deep inside itself for all values under given key.

        If key exists in container and is unique we get list with single value.
        If multiple such keys exist in container - we get list of all that values
        If given key doesn't exist inside container we raise NotFoundKeyError

        :param key:                    key to search value by
        :return:                       all values under key
        """
        return KeyFindingDict._get_all_values_by_key(self, key)

    @staticmethod
    def _get_all_values_by_key(container, key):
        # TODO figure out mechanism that prevents user from wrong usage:  get_all_values_by_key('erab_id') returns all for: erabToAdd & erabToRelease
        param_name = "container"
        paths2key = KeyFindingDict._find_paths2key(container, key, param_name)
        all_values = []
        for single_path2key in paths2key:
            value = eval(single_path2key)  # pylint: disable=eval-used
            all_values.append(value)

        if all_values == []:
            raise NotFoundKey(key=key, container=container)

        return all_values

    def key_not_occurred(self, key):
        """
        Search deep inside itself if given key is NOT present.

        If key doesn't exists True is returned, thats why NotFoundKey exception is handled gracefully.
        If given key exist inside container we raise FoundKey

        :param key:                    key to search value by
        :raises FoundKey:              when key exists within container
        :return:                       True is not exists
        """
        captured_values = []
        try:
            captured_values = KeyFindingDict.get_all_values_by_key(self, key)
        except NotFoundKey:
            pass

        if captured_values:
            raise FoundKey(key=key, container=self)

        return True

    @staticmethod
    def _find_paths2key(container, key, container_name=""):
        """
        :param container: container to be searched
        :param key: key to search value by
        :param container_name: container name needed to build full key path for later value evaluation
        :return: paths2key: aggregation of founded paths to key
        """
        paths2key = []
        if isinstance(container, list):
            paths2key_from_list = KeyFindingDict._find_paths2key_in_list(container, key, container_name)
            paths2key.extend(paths2key_from_list)
        elif isinstance(container, dict):
            paths2key_from_dict = KeyFindingDict._find_paths2key_in_dict(container, key, container_name)
            paths2key.extend(paths2key_from_dict)
        return paths2key

    @staticmethod
    def _find_paths2key_in_list(container, key, container_name):
        """
        :param container: list to be searched
        :param key: key to search value by
        :param container_name: container name needed to build full key path for later value evaluation
        :return: paths2key: aggregation of founded paths to key
        """
        paths2key = []
        for (index, elem) in enumerate(container):
            paths2key_from_element = KeyFindingDict._find_paths2key(elem, key, "%s[%s]" % (container_name, index))
            paths2key.extend(paths2key_from_element)
        return paths2key

    @staticmethod
    def _find_paths2key_in_dict(container, key, container_name):
        """
        :param container: dict to be searched
        :param key: key to search value by
        :param container_name: container name needed to build full key path for later value evaluation
        :return: paths2key: aggregation of founded paths to key
        """
        paths2key = []
        for key_of_container in container.keys():
            if key_of_container == key:
                paths2key.append("%s['%s']" % (container_name, key_of_container))
            paths2key_from_element = KeyFindingDict._find_paths2key(container[key_of_container], key, "%s['%s']" % (container_name, key_of_container))
            paths2key.extend(paths2key_from_element)
        return paths2key


class MessageField(KeyFindingDict):
    """Message Field"""
    def __str__(self):
        return f'{pprint.pformat(dict(self))}'

    def __repr__(self):
        return f'{dict(self)}'


class Message(KeyFindingDict):
    """
    Base class for all messages
    Message simplifies access and validation of fields inside dictionary holding message data
    """

    def __init__(self, message_dict, meta_data_dict):
        """
        Basic initialization.

        :param message_dict:
        :param meta_data_dict:
        """
        super(Message, self).__init__(message_dict)
        self._available_attributes = []
        for k, v in meta_data_dict.items():
            setattr(self, k, v)
            self._available_attributes.append(k)

    def __str__(self):
        class_name = self.__class__.__name__
        metadata_str = "\n".join([f'{k}={v}' for k, v in self._get_metadata()])
        return f'{class_name}({metadata_str}\n{pprint.pformat(dict(self))})'

    def __repr__(self):
        class_name = self.__class__.__name__
        metadata_str = "".join([f'{k}={v};' for k, v in self._get_metadata()])
        return f'{class_name}({metadata_str}{dict(self)})'

    def _get_metadata(self):
        return [(item, self.__getattribute__(item)) for item in self._available_attributes]


def container_truncated_dump(container, truncation_len=220, visible_text_len=200):
    """
    :return: formatted string, e.g. below:

    ::

        Message(memo={'MME-UE-S1AP-ID': u'49971'} occurrence_time=110011.1112 {u'S1AP-PDU': {u'initiatingMessage': {u'criticality': u'ignore (1)',
        ...
        u'rrc-TransactionIdentifier': u'0'}}}}}}}}}]}}}}})

    """
    visible_start_len = int(visible_text_len * 3 / 4)
    visible_end_len = int(visible_text_len * 1 / 4)
    container_dump = str(container)
    if len(container_dump) > truncation_len:  # don't print whole container if it is big
        parts = container_dump.split()  # we don't want to see truncated keys if possible
        start = ' '.join(parts[:10])
        if len(start) > visible_start_len:
            start = start[:visible_start_len]
        end = ' '.join(parts[-4:])
        if len(end) > visible_end_len:
            end = end[-visible_end_len:]
        container_dump = "%s\n   ...\n   %s" % (start, end)
    return container_dump


class AmbiguousKey(KeyError):
    """Key os ambiguous."""
    def __init__(self, key, container, access_paths2key):
        """
        Basic initialization.

        :param key:
        :param container:
        :param access_paths2key:
        """
        super(AmbiguousKey, self).__init__()
        self.key = key
        self.container = container
        self.access_paths2key = access_paths2key

    def __str__(self):
        access_parts = '\n'.join(self.access_paths2key)
        access = "Container's value access via key '%s' has following possibilities:\n%s" % (self.key, access_parts)
        container_dump = container_truncated_dump(self.container)
        err = "Key '%s' is not unique inside container:\n%s;\n%s" % (self.key, container_dump, access)
        return err


class NotFoundKey(KeyError):
    """Key not found."""
    def __init__(self, key, container):
        """
        Basic initialization.

        :param key:
        :param container:
        """
        super(NotFoundKey, self).__init__()
        self.key = key
        self.container = container

    def __str__(self):
        container_dump = container_truncated_dump(self.container)
        err = "Key '%s' doesn't exist inside container:\n%s, xxxx" % (self.key, container_dump)
        return err


class FoundKey(NotFoundKey):
    """Key found"""
    def __str__(self):
        container_dump = container_truncated_dump(self.container)
        err = "Key '%s' exist inside container:\n%s, xxxx" % (self.key, container_dump)
        return err
